/**
 * Earlier capability profile manifests, kept as data.
 *
 * What this is: every profile manifest an earlier build carried, stored as it
 * was so its manifest ref recomputes from these bytes. Capability entries are
 * pooled, because most rows repeat across profiles and versions.
 *
 * How it fits: profile-compatibility.ts checks each stored manifest against
 * the current one, so an export pinned to an earlier manifest stays
 * continuable while the current manifest extends it. Generated by
 * scripts/capture-profile-manifest-history.ts, run before a manifest changes.
 * A hand edit changes the recomputed ref, and the stored manifest then
 * matches no export.
 */
import type { ProfileCapabilityManifest } from './capability-profile.js';
import type { Profile } from './vocab.js';
/** Each profile's earlier manifests, oldest first. */
export declare const PROFILE_MANIFEST_PREDECESSORS: Readonly<Record<Profile, readonly ProfileCapabilityManifest[]>>;
